/* Presentation only. No command here can reach the hardware engine. */
window.DevicePages=(()=>{
  const uiSettings={sleep:{min:1,max:15,value:5},idleLight:{min:1,max:15,value:5},keyIdle:{min:15,max:60,value:15}};
  const disabled='disabled aria-disabled="true"';
  const {panel,unavailable,slider,toggle,stage:hero}=UI;
  function values(){return profile().ui||{};}
  function lighting(id,options={}){const p=profile(),u=values();
    const lights=panel('BRIGHTNESS',`<label class="switch-row"><input type="checkbox" id="lighting-enabled" ${p.brightness>0?'checked':''}><span>Preview lighting enabled</span></label><div class="device-value"><output id="brightness-value">${p.brightness}%</output></div><input id="brightness" aria-label="Brightness" type="range" min="0" max="100" value="${p.brightness}"><div class="range-extents"><span>0</span><span>100</span></div>`);
    const effects=panel('EFFECTS',`<div class="segmented"><button class="selected" disabled>Quick effects</button><button disabled title="Chroma Studio is not integrated">Advanced effects</button></div><p>These values are saved in the local profile without being applied to the device.</p><label class="device-field">Effect<select id="effect">${['Static','Breathing','Spectrum'].map(v=>`<option ${v===p.effect?'selected':''}>${v}</option>`).join('')}</select></label><label class="device-field">Color<div class="inline"><input id="color" type="color" value="${p.color}"><output id="color-value">${p.color.toUpperCase()}</output></div></label>`);
    const off=unavailable('SWITCH OFF LIGHTING',toggle('When the display is turned off',false,disabled)+toggle('After an idle period',false,disabled)+slider('idleLight','Minutes',u.idleLight||5,1,15,disabled),'Lighting automation is not connected to the engine in this interface.');
    const smart=unavailable('SMART DIMMING',toggle('Dim lighting while in use',false,disabled)+'<div class="segmented"><button disabled>0%</button><button disabled>25%</button><button disabled>50%</button></div>','Support for this feature has not been established for this model.');
    return `${options.hero?hero(id):''}<div class="device-columns"><div>${lights}${options.autoOff?off:''}</div><div>${effects}${options.smartDimming?smart:''}</div></div>`;
  }
  function performance(){const d=M.device(deviceId),p=profile(),cap=d.capabilities.dpi;return `<div class="device-columns"><div>${panel('SENSITIVITY',`<p>Choose a DPI stage. Values only change the local profile draft.</p><div class="stages">${p.stages.map((v,i)=>`<button class="stage ${i===p.stage?'active':''}" data-stage="${i}" aria-pressed="${i===p.stage}"><small>STAGE ${i+1}</small>${v}</button>`).join('')}</div><div class="slider-value"><output id="dpi-value">${p.stages[p.stage]} DPI</output><label>DPI <input id="dpi-number" type="number" min="${cap.min}" max="${cap.max}" step="${cap.step}" value="${p.stages[p.stage]}" aria-label="DPI numeric sensitivity"></label></div><input id="dpi-range" type="range" min="${cap.min}" max="${cap.max}" step="${cap.step}" value="${p.stages[p.stage]}" aria-label="DPI sensitivity"><div class="range-extents"><span>${cap.min}</span><span>${cap.max.toLocaleString(I18n.locale)}</span></div>`)}${unavailable('WINDOWS PROPERTIES','<button disabled>Open mouse properties</button>','This preview does not open system panels.')}</div><div>${panel('POLLING RATE',`<p>Values are limited to this model’s declaration in Secbird.</p><label class="device-field">Polling rate<select id="polling">${d.capabilities.polling.map(h=>`<option value="${h}" ${p.polling===h?'selected':''}>${h} Hz</option>`).join('')}</select></label>`)}${unavailable('AUTOMATIC POLLING RATE SWITCHING',toggle('Enable in full screen',false,disabled),'Not integrated; no polling rate adjustments run in the background.')}${unavailable('SENSITIVITY MATCHING','<p>Import calibration from another mouse.</p><button disabled>Calibrate</button>','No sensitivity conversion algorithm is integrated.')}</div></div>`;}
  function customizeMouse(){const p=profile(),labels={'1':'Left click','2':'Right click','3':'Middle click','4':'Back','5':'Forward','6':'Cycle DPI'};return `<div class="customize-layout"><div class="device-stage">${DeviceVisuals.render(deviceId)}<small>Placeholder icon · select buttons from the list</small></div>${panel('BUTTON ASSIGNMENTS',`<div class="binding-list">${Object.entries(labels).map(([n,label])=>`<button class="binding-choice ${selectedButton===n?'selected':''}" data-button="${n}"><span>${n} · ${label}</span><small>${esc(p.buttons[n]||label)}</small></button>`).join('')}</div><label class="device-field">Button ${selectedButton}<select id="binding" ${selectedButton==='1'?'disabled':''}>${[...new Set([p.buttons[selectedButton]||labels[selectedButton],'Right click','Middle click','Back','Forward','Cycle DPI','Copy','Paste','Disabled'])].map(v=>`<option>${esc(v)}</option>`).join('')}</select></label><p>Primary left click is protected. Assignments are local only.</p>`)}</div><div class="device-columns">${unavailable('SCROLL WHEEL', '<div class="segmented"><button disabled>Tactile</button><button disabled>Free spin</button></div>'+toggle('Smart-Reel',false,disabled)+toggle('Scroll acceleration',false,disabled),'Advanced scroll wheel commands are not integrated in this preview.')}${unavailable('MULTI-DEVICE PAIRING','<button disabled>Open pairing utility</button>','No HyperSpeed tool or Razer service is used.')}</div>`;}
  let selectedKey='A';
  function customizeKeyboard(){const keys=['Esc','1','2','3','4','5','6','7','8','9','0','⌫','Tab','A','Z','E','R','T','Y','U','I','O','P','↵','Caps','Q','S','D','F','G','H','J','K','L','M','Shift','Ctrl','Win','Alt','Space','Fn','←','↓','↑','→'];return `<div class="keyboard-workspace"><div class="keyboard-placeholder">${DeviceVisuals.render(deviceId)}</div><div class="key-picker" aria-label="Key selection preview">${keys.map(k=>`<button data-key-preview="${k}" class="${selectedKey===k?'selected':''}">${k}</button>`).join('')}</div><small>Illustrative key selector · does not reproduce the physical layout</small></div><div class="device-columns">${unavailable('KEY ASSIGNMENT',`<p>Selected key: <strong>${selectedKey}</strong></p><select disabled aria-label="Key assignment"><option>Default function</option></select>`,'The current API does not provide keyboard remapping. The selection above is a preview.')}${unavailable('GAMING MODE AND SNAP TAP',toggle('Gaming mode',false,disabled)+toggle('Disable Windows key',false,disabled)+toggle('Snap Tap',false,disabled),'These features are not integrated with the existing engine.')}${unavailable('HYPERSPEED PAIRING','<button disabled>Open pairing utility</button>','Secbird does not perform pairing in this phase.')}${unavailable('KEYBOARD PROPERTIES','<button disabled>Open Windows properties</button>','System access is not integrated.')}</div>`;}
  function power(id,options={}){const u=values();return `<div class="device-columns">${options.sleepPreview?panel('WIRELESS SLEEP',`<p>Sleep after an idle period. Local setting, not sent to the device.</p>${slider('sleep','Minutes',u.sleep||5,1,15)}`):unavailable('KEYBOARD DIMMING',toggle('Dim lighting after inactivity',false,disabled)+slider('idleLight','Minutes',5,1,15,disabled),'This keyboard feature has not been validated in the engine.')}${unavailable(options.sleepPreview?'LOW POWER MODE':'POWER SAVING',options.sleepPreview?slider('lowBattery','Battery threshold (%)',20,5,100,disabled):slider('keyIdle','Minutes before switch-off',15,15,60,disabled),'Command not integrated; no system or hardware behavior is changed.')}</div>`;}
  function calibration(){return `<div class="device-info-banner"><h1>SURFACE CALIBRATION</h1><p>Tracking distance preview. No calibration procedure is executed.</p></div><div class="narrow-panel">${unavailable('SMART TRACKING',toggle('Enable asymmetric distance',false,disabled)+slider('tracking','Tracking distance',1,1,3,disabled)+'<button disabled>Reset calibration</button>','Surface calibration and lift-off are not integrated. No hardware reset or firmware changes.')}</div>`;}
  function audio(){return hero(deviceId)+`<div class="device-columns">${unavailable('VOLUME',toggle('Enable audio output',false,disabled)+slider('volume','Volume',50,0,100,disabled),'Windows audio control is not implemented; a dock entry in the HID database does not establish audio control support.')}${unavailable('AUDIO PROPERTIES','<button disabled>Open sound properties</button><p>System output and mixer.</p>','No system audio device changes.')}</div>`;}
  function argb(options={}){const count=options.ports||6;const half=Math.ceil(count/2);const first=Array.from({length:half},(_,i)=>i+1);const second=Array.from({length:count-half},(_,i)=>i+half+1);return `<div class="argb-layout"><div>${second.map(n=>port(n,options)).join('')}</div><div class="argb-center">${DeviceVisuals.render(deviceId)}<div class="inline"><button disabled title="Auto detection is not integrated">Auto</button><button disabled title="Hardware detection is not integrated">Detect</button></div><p>ARGB configuration is not integrated with the engine.</p></div><div>${first.map(n=>port(n,options)).join('')}</div></div>`;}
  function port(n,options){return unavailable(`PORT ${n}`,`<label class="device-field">Device type<select disabled><option>LED strip</option><option>Fan</option></select></label><label class="device-field">LED count<input type="number" min="1" max="${options.maxLeds||80}" value="30" disabled></label><button class="text-link" disabled>Add a 90° bend</button>`,'Layout preview; LED types and counts have not been detected.');}
  const renderers={
    'lighting':(id,options)=>lighting(id,options),
    'performance':()=>performance(),
    'mouse-customize':()=>customizeMouse(),
    'keyboard-customize':()=>customizeKeyboard(),
    'power':(id,options)=>power(id,options),
    'calibration':()=>calibration(),
    'audio':()=>audio(),
    'information':id=>panel('DETECTED DEVICE',`<p>VID 1532 · PID ${esc(DeviceRegistry.get(id).pid)} · ${DeviceRegistry.get(id).interfaces} interface(s) HID.</p><p>No configuration page is registered for this model. Command support is not assumed.</p>`,'local'),
    'ports':(_,options)=>argb(options)
  };
  function definitions(id){const d=DeviceRegistry.get(id);return d.pages.filter(p=>!p.requires||!!d.capabilities[p.requires]);}
  function render(id,tab){
    const definition=definitions(id).find(p=>p.label===tab);
    const renderer=definition&&renderers[definition.view];
    const content=renderer?renderer(id,definition.options||{}):unavailable('PAGE UNAVAILABLE','','No component registered for this page.');
    const body=DeviceRegistry.get(id).detected||definition?.status==='unavailable'?`<fieldset disabled class="disabled-view" aria-label="Hardware settings are not connected">${content}</fieldset>`:content;
    return `<div class="device-page-content" id="device-content" role="tabpanel" aria-labelledby="tab-${tab}"><div class="local-editing-banner"><span>READ ONLY</span><p>Profile draft: <strong>${esc(store[id].active)}</strong>. Live device detected; current settings and battery have not been read. No commands sent.</p><button data-page="profiles">Manage profiles</button></div>${body}</div>`;
  }
  document.addEventListener('click',event=>{const key=event.target.closest('[data-key-preview]');if(key){selectedKey=key.dataset.keyPreview;window.render();}});
  document.addEventListener('change',event=>{const e=event.target;if(e.id==='lighting-enabled'){profile().brightness=e.checked?75:0;save();window.render();}});
  document.addEventListener('input',event=>{const e=event.target;if(e.disabled||!e.dataset.pref)return;const spec=uiSettings[e.dataset.pref];if(!spec||!Number.isFinite(Number(e.value)))return;const v=Math.max(spec.min,Math.min(spec.max,Number(e.value)));profile().ui={...profile().ui,[e.dataset.pref]:v};document.querySelector(`[data-readout="${e.dataset.pref}"]`).textContent=v;save();});
  return {tabs:id=>definitions(id).map(p=>p.label),render};
})();
